contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount <= address(this).balance);

        (uint beforeBal, ) = c.Acc(address(this));

        bool reverted;
        try c.Put{value: amount}(0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterBal, ) = c.Acc(address(this));

        // Put must revert exactly when the balance update would overflow,
        // where beforeBal is the caller's balance before this call.
        assert(reverted == (beforeBal + amount < beforeBal));
    }

    receive() external payable {}
}

