contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint collectAmount, uint unlockTime) public payable {
        require(address(this).balance >= putAmount);

        c.Put{value: putAmount}(unlockTime);

        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        bool preconditionMet =
            (beforeBalance >= c.MinSum() &&
             beforeBalance >= collectAmount &&
             block.timestamp > beforeUnlockTime);

        assert(
            reverted == !preconditionMet
        );
        assert(
            reverted || afterBalance == beforeBalance - collectAmount
        );
        assert(
            !reverted || afterBalance == beforeBalance
        );
        assert(afterUnlockTime == beforeUnlockTime);
    }

    receive() external payable {}
}

