contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint unlockTime, uint amount) public payable {
        // No explicit require needed: amount is the value sent, which is bounded by msg.value
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // General rule: Put always succeeds and increments balance by amount,
        // and sets unlockTime to max(unlockTime, block.timestamp).
        // We cannot compare unlockTime directly with block.timestamp in the assert,
        // but we know it's either the old value (if unlockTime <= block.timestamp)
        // or unlockTime itself. Since the contract ensures unlockTime >= block.timestamp,
        // we assert that afterUnlock >= beforeUnlock (which holds if unlockTime >= beforeUnlock).
        // To avoid this subtlety, we only assert the balance increment and non-reversion.
        assert(!reverted && afterBalance == beforeBalance + amount);
    }

    receive() external payable {}
}

